def check_k1(k1):
    """
    Checks if k1 satisfies the equation: floor(22 * floor(22 * floor(96/k1))) = k1
    """
    if k1 <= 0:
        return None, "k1 must be positive"

    # Z1 = floor(96/k1)
    Z1 = int(96 / k1)

    # Z2 = floor(22 * Z1)
    Z2 = int(22 * Z1)

    # Z3 = floor(22 * Z2)
    Z3 = int(22 * Z2)

    # Check condition
    if Z3 == k1:
        return k1, True
    else:
        return Z3, False

